// the brass verse: eight cycles
let verse = "<[4@2 3 2@2 0 1 2] [4@2 5 4@2 2 1 0] [4@2 3 2@2 0 2 4] [5@3 4 3 2 ~ 0] [2@2 3 4@2 5 4 2] [5@2 6 5@2 4 3 2] [4@2 2 0@2 1 2 3] [0@6 ~ ~]>"
